#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    if (n >= 4 && m >= 4) {
        cout << n * m - ((n * m) % 2) << endl;
    } else {
        int smaller = min(n, m);
        int larger = max(n, m);
        if (smaller == 1) {
            int r = larger;
            if (r % 6 == 5) {
                cout << (r / 6) * 6 + 4 << endl;
            } else if (r % 6 == 4) {
                cout << (r / 6) * 6 + 2 << endl;
            } else {
                cout << (r / 6) * 6 << endl;
            }
        } else if (smaller == 2 && larger == 7) {
            cout << 12 << endl;
        } else if ((smaller == 2 && larger >= 4) || (smaller == 3 && larger >= 4)) {
            cout << n * m - ((n * m) % 2) << endl;
        } else {
            int d[5][5] = {
                {0, 0, 0, 2, 4},
                {0, 0, 4, 8, 10},
                {0, 0, 8, 12, 14},
                {0, 0, 0, 16, 20},
                {0, 0, 0, 0, 24}
            };
            cout << d[smaller - 1][larger - 1] << endl;
        }
    }
    return 0;
}
